with with_dims as (select e.id, e.session_id, e.event_type, e.page, e.event_time, p.browser, p.device, p.country from web_events e left join sessions p on e.session_id = p.id where p.device in ('tablet', 'desktop')) select s.id, s.session_id, s.event_time, s.device, s.country, case when country rlike '^(SG|UK)$' then 'PRIORITY' else 'GROUP_A' end as country_zone, (select avg(x.duration_sec) from web_events x where x.session_id = s.session_id) as avg_web_event_duration_sec from with_dims s order by device nulls first;
